<div class="space-y-5 max-w-5xl"><?php include __DIR__.'/_nav.php'; ?><div><h1 class="text-xl font-semibold">Email Settings</h1><p class="text-sm text-slate-500 mt-1">Mailgun delivery, sender identity, compliance footer, and reusable images.</p></div>
<form method="POST" action="/settings/email" class="space-y-5"><?= csrfField() ?><div class="bg-white border rounded-lg p-5"><h2 class="font-medium mb-4">Mailgun</h2><div class="grid sm:grid-cols-2 gap-4"><label class="text-sm">Region<select name="region" class="mt-1 w-full border rounded px-3 py-2"><option value="eu">EU</option><option value="us" <?= ($config['region']??'eu')==='us'?'selected':'' ?>>US</option></select></label><label class="text-sm">Sending domain<input name="sending_domain" value="<?= e($config['sending_domain']??'') ?>" placeholder="mg.example.com" class="mt-1 w-full border rounded px-3 py-2"></label><label class="text-sm">Private API key<input type="password" name="api_key" placeholder="<?= !empty($config['api_key'])?'Configured — leave blank to keep':'key-…' ?>" class="mt-1 w-full border rounded px-3 py-2"></label><label class="text-sm">Webhook signing key<input type="password" name="webhook_signing_key" placeholder="<?= !empty($config['webhook_signing_key'])?'Configured — leave blank to keep':'Signing key' ?>" class="mt-1 w-full border rounded px-3 py-2"></label></div></div>
<div class="bg-white border rounded-lg p-5"><h2 class="font-medium mb-4">Sender and brand</h2><div class="grid sm:grid-cols-2 gap-4"><label class="text-sm">From name<input name="from_name" value="<?= e($config['from_name']??'') ?>" class="mt-1 w-full border rounded px-3 py-2"></label><label class="text-sm">From email<input type="email" name="from_email" value="<?= e($config['from_email']??'') ?>" class="mt-1 w-full border rounded px-3 py-2"></label><label class="text-sm">Reply-to<input type="email" name="reply_to" value="<?= e($config['reply_to']??'') ?>" class="mt-1 w-full border rounded px-3 py-2"></label><label class="text-sm">Brand colour<input type="color" name="brand_colour" value="<?= e($config['brand_colour']??'#4f46e5') ?>" class="mt-1 block h-10 w-16 border rounded"></label><label class="text-sm">Business name<input name="business_name" value="<?= e($config['business_name']??'') ?>" class="mt-1 w-full border rounded px-3 py-2"></label><label class="text-sm">Privacy URL<input type="url" name="privacy_url" value="<?= e($config['privacy_url']??'') ?>" class="mt-1 w-full border rounded px-3 py-2"></label><label class="text-sm sm:col-span-2">Business address<textarea required name="business_address" rows="3" class="mt-1 w-full border rounded px-3 py-2"><?= e($config['business_address']??'') ?></textarea></label><div class="flex gap-4"><label class="text-sm"><input type="checkbox" name="tracking_opens" <?= !isset($config['tracking_opens'])||$config['tracking_opens']?'checked':'' ?>> Default open tracking</label><label class="text-sm"><input type="checkbox" name="tracking_clicks" <?= !isset($config['tracking_clicks'])||$config['tracking_clicks']?'checked':'' ?>> Default click tracking</label></div></div></div><button class="px-4 py-2 bg-accent-600 text-white rounded text-sm">Save settings</button></form>
