<div class="bg-white border rounded-lg p-5"><h2 class="font-medium mb-3">Email images</h2><form method="POST" enctype="multipart/form-data" action="/settings/email/assets" class="flex flex-wrap gap-2 items-end"><?= csrfField() ?><label class="text-sm">JPEG, PNG, or GIF<input required type="file" name="asset" accept="image/jpeg,image/png,image/gif" class="block mt-1"></label><label class="text-sm">Default alt text<input name="alt_text" class="mt-1 border rounded px-3 py-2"></label><button class="px-3 py-2 border rounded text-sm">Upload</button></form><?php if($assets): ?><div class="grid grid-cols-3 sm:grid-cols-5 gap-3 mt-4"><?php foreach($assets as $a): ?><div><img src="/email/assets/<?= e($a['public_token']) ?>/<?= rawurlencode($a['original_name']) ?>" alt="<?= e($a['alt_text']) ?>" class="aspect-square object-cover rounded border"><p class="text-xs truncate mt-1"><?= e($a['original_name']) ?></p></div><?php endforeach ?></div><?php endif ?></div>
